    """Query built from the chunk's keyword field, or extracted terms."""
    if keywords:
        # Strip list-bracket syntax and clean separators.
        parts = [k.strip("[]\"' ") for k in re.split(r"[،,؛;\n]+", keywords) if k.strip("[]\"' ")]
