input.newString:
{% if results %}
<div class="card">
    <h3>Hit Rate by Query Format</h3>
    <div class="table-container">
        <table class="data-table">
            <thead>
                <tr>
                    <th>Format</th>
                    <th>Queries</th>
                    <th>Hit@K</th>
                    <th>Top-1</th>
                    <th>MRR</th>
                    <th>Avg Rank</th>
                    <th>Avg Latency (ms)</th>
                </tr>
            </thead>
            <tbody>
                {% for fmt, agg in (results.by_format or {}).items() %}
                <tr>
                    <td>{{ fmt }}</td>
                    <td>{{ agg.queries }}</td>
                    <td>{{ "%.1f"|format(agg.hit_rate * 100) }}%</td>
                    <td>{{ "%.1f"|format(agg.top1_hit_rate * 100) }}%</td>
                    <td>{{ "%.3f"|format(agg.mrr) }}</td>
                    <td>{{ agg.avg_rank }}</td>
                    <td>{{ "%.1f"|format(agg.avg_latency_ms) }}</td>
                </tr>
                {% endfor %}
            </tbody>
        </table>
    </div>
</div>
{% endif %}

{% if ir_metrics and ir_metrics.metrics %}
<div class="card">
    <h3>IR Metrics (ranx / pure-Python)</h3>
    <div class="table-container">
        <table class="data-table">
            <thead><tr><th>Metric</th><th>Value</th></tr></thead>
            <tbody>
                {% for metric, value in (ir_metrics.metrics or {}).items() %}
                <tr><td>{{ metric }}</td><td>{{ "%.4f"|format(value) }}</td></tr>
                {% endfor %}
            </tbody>
        </table>
    </div>
</div>
{% endif %}

<div class="charts-grid">
    <div class="chart-card">
        <h3>Hit@5 by Query Format</h3>
        <canvas id="hitChart" height="250"></canvas>
    </div>
    <div class="chart-card">
        <h3>Top-1 Accuracy by Query Format</h3>
        <canvas id="top1Chart" height="250"></canvas>
    </div>
    <div class="chart-card">
        <h3>MRR by Query Format</h3>
        <canvas id="mrrChart" height="250"></canvas>
    </div>
    <div class="chart-card">
        <h3>Avg Latency by Query Format</h3>
        <canvas id="latencyChart" height="250"></canvas>
    </div>
</div>

<script>
(function() {
    const results = {{ results | tojson }};
    if (!results || !results.by_format) return;

    const formats = Object.keys(results.by_format);
    const hitRates = formats.map(f => (results.by_format[f].hit_rate * 100).toFixed(1));
    const top1Rates = formats.map(f => (results.by_format[f].top1_hit_rate * 100).toFixed(1));
    const mrrs = formats.map(f => results.by_format[f].mrr.toFixed(3));
    const latencies = formats.map(f => results.by_format[f].avg_latency_ms.toFixed(1));

    new Chart(document.getElementById('hitChart'), {
        type: 'bar',
        data: { labels: formats, datasets: [{ label: 'Hit@5 (%)', data: hitRates, backgroundColor: '#3b82f6' }] },
        options: { responsive: true, indexAxis: 'y', plugins: { legend: { display: false } }, scales: { x: { beginAtZero: true, max: 100 } } }
    });

    new Chart(document.getElementById('top1Chart'), {
        type: 'bar',
        data: { labels: formats, datasets: [{ label: 'Top-1 (%)', data: top1Rates, backgroundColor: '#10b981' }] },
        options: { responsive: true, indexAxis: 'y', plugins: { legend: { display: false } }, scales: { x: { beginAtZero: true, max: 100 } } }
    });

    new Chart(document.getElementById('mrrChart'), {
        type: 'bar',
        data: { labels: formats, datasets: [{ label: 'MRR', data: mrrs, backgroundColor: '#f59e0b' }] },
        options: { responsive: true, indexAxis: 'y', plugins: { legend: { display: false } }, scales: { x: { beginAtZero: true, max: 1 } } }
    });

    new Chart(document.getElementById('latencyChart'), {
        type: 'bar',
        data: { labels: formats, datasets: [{ label: 'Latency (ms)', data: latencies, backgroundColor: '#ef4444' }] },
        options: { responsive: true, indexAxis: 'y', plugins: { legend: { display: false } }, scales: { x: { beginAtZero: true } } }
    });
})();
</script>

