"""Base classes for synthetic data generators."""

from __future__ import annotations

import abc
import json
import logging
from dataclasses import dataclass
from pathlib import Path
from typing import Any, Dict, List, Optional

logger = logging.getLogger(__name__)


@dataclass
class GenerationResult:
    """Result of a generation task."""
    success: bool
    data: Any
    metadata: Dict[str, Any]
    error: Optional[str] = None


class BaseGenerator(abc.ABC):
    """Abstract base class for all generators."""

    def __init__(
        self,
        llm_client: Any,
        prompt_template: str,
        config: Dict[str, Any],
    ) -> None:
        self._llm = llm_client
        self._prompt_template = prompt_template
        self._config = config

    @abc.abstractmethod
    def generate(self, input_data: Dict[str, Any]) -> GenerationResult:
        """Generate synthetic data from input."""
        pass

    def _load_prompt(self, prompt_name: str) -> str:
        """Load prompt template from file."""
        prompt_path = Path(__file__).parent.parent / "prompts" / f"{prompt_name}.txt"
        if prompt_path.exists():
            return prompt_path.read_text(encoding="utf-8")
        raise FileNotFoundError(f"Prompt template not found: {prompt_name}")

    def _parse_json_response(self, response: str) -> Any:
        """Parse JSON from LLM response, handling common issues."""
        import re
        text = str(response).strip()

        # Try direct JSON parse
        try:
            return json.loads(response)
        except json.JSONDecodeError:
            pass

        # Try to extract JSON from markdown code blocks
        import re
        code_block = re.search(r'```(?:json)?\s*(.*?)\s*```', response, re.DOTALL)
        if code_block:
            try:
                return json.loads(code_block.group(1).strip())
            except json.JSONDecodeError:
                pass

        # Try to find JSON array or object in text
        for pattern in [r'\[.*\]', r'\{.*\}']:
            match = re.search(pattern, response, re.DOTALL)
            if match:
                try:
                    return json.loads(match.group(0))
                except json.JSONDecodeError:
                    continue

        raise ValueError(f"Could not parse JSON from response: {response[:200]}...")

    def _build_prompt(self, template: str, **kwargs) -> str:
        """Format prompt template with variables."""
        return self._prompt_template.format(**kwargs)

    def _call_llm(
        self,
        prompt: str,
        max_tokens: int = 1024,
        temperature: float = 0.4,
    ) -> str:
        """Call LLM and return text response."""
        from kb_manager.llm import LLMResponse

        response = self._llm.generate(
            prompt,
            max_tokens=max_tokens,
            temperature=temperature,
        )
        return response.text if isinstance(response, str) else response.text

"""QA pair generator for synthetic data generation."""

from __future__ import annotations

import json
import logging
from typing import Any, Dict, List, Optional

from synthetic_generation.generators.base import BaseGenerator, GenerationResult

logger = logging.getLogger(__name__)


class QAGenerator:
    """Generates QA pairs from chunk content."""

    def __init__(
        self,
        llm_client: Any,
        config: Dict[str, Any],
    ) -> None:
        self._llm = llm_client
        self._config = config

        # Load prompt template
        from pathlib import Path
        prompt_path = Path(__file__).parent.parent / "prompts" / "qa_generation.txt"
        self._prompt_template = Path(__file__).parent.parent.joinpath("prompts", "qa_generation.txt").read_text(encoding="utf-8")

        # Query type weights
        self._type_weights = config.get("generation", {}).get("query_types", {
            "verbatim": 0.15,
            "paraphrase": 0.20,
            "conversational": 0.20,
            "typo": 0.15,
            "keyword_only": 0.15,
            "reworded": 0.15,
        })

        self._num_queries = config.get("generation", {}).get("num_samples_per_chunk", 8)
        self._min_per_type = max(1, self._num_queries // len(self._type_weights))

    def generate(self, chunk_content: str, chunk_id: str) -> List[Dict[str, Any]]:
        """Generate QA pairs for a chunk."""
        # Build prompt with chunk content
        prompt = self._build_prompt(chunk_content)

        # Call LLM
        response = self._call_llm(prompt)

        # Parse response
        try:
            queries = self._parse_response(response, chunk_id)
            return queries
        except Exception as e:
            logger.warning(f"Failed to parse QA generation for chunk {chunk_id}: {e}")
            return self._fallback_queries(chunk_id)

    def _build_prompt(self, chunk_content: str) -> str:
        """Build prompt for QA generation."""
        num_queries = self._config.get("generation", {}).get("num_samples_per_chunk", 8)
        min_per_type = max(1, self._num_queries // 6)

        # Truncate chunk if too long
        max_len = self._config.get("generation", {}).get("max_chunk_length", 2000)
        content = chunk_content[:max_len]

        # Load prompt template
        from pathlib import Path
        template_path = Path(__file__).parent.parent / "prompts" / "qa_generation.txt"
        template = Path(template_path).read_text(encoding="utf-8")

        return template.format(
            chunk_content=content,
            num_queries=self._num_queries,
            min_per_type=max(1, self._num_queries // 6),
        )

    def _call_llm(self, prompt: str) -> str:
        """Call LLM and return text response."""
        try:
            response = self._llm.generate(
                prompt,
                max_tokens=1024,
                temperature=0.4,
            )
            return response.text if hasattr(response, 'text') else str(response)
        except Exception as e:
            logger.error(f"LLM call failed: {e}")
            raise

    def _parse_response(self, response: str, chunk_id: str) -> List[Dict[str, Any]]:
        """Parse LLM response into list of queries."""
        import json
        import re

        text = str(response).strip()

        # Try to parse as JSON
        try:
            data = json.loads(response)
            if isinstance(data, list):
                return self._normalize_queries(data, chunk_id)
        except json.JSONDecodeError:
            pass

        # Try to extract JSON array
        import re
        match = re.search(r'\[.*\]', response, re.DOTALL)
        if match:
            try:
                data = json.loads(match.group(0))
                if isinstance(data, list):
                    return self._normalize_queries(data, chunk_id)
            except json.JSONDecodeError:
                pass

        # Fallback
        logger.warning("Failed to parse LLM response as JSON")
        return self._fallback_queries()

    def _normalize_queries(self, queries: List[Dict], chunk_id: str) -> List[Dict]:
        """Normalize query format and add metadata."""
        normalized = []
        for q in queries:
            if not isinstance(q, dict):
                continue
            query_text = q.get("query", "").strip()
            qtype = q.get("type", "unknown")

            if not query_text:
                continue

            normalized.append({
                "query": query_text,
                "type": qtype,
                "chunk_id": chunk_id,
                "expected_chunk_id": chunk_id,
            })
        return normalized

    def _fallback_queries(self, chunk_id: str = "") -> List[Dict[str, Any]]:
        """Fallback queries when generation fails."""
        types = ["verbatim", "paraphrase", "conversational", "typo", "keyword_only", "reworded"]
        return [
            {"query": f"فallback query {i}", "type": t, "chunk_id": chunk_id, "expected_chunk_id": chunk_id}
            for i, t in enumerate(types)
        ]

"""Conversational generator for multi-turn synthetic conversations."""

from __future__ import annotations

import json
import logging
import re
from pathlib import Path
from typing import Any, Dict, List, Optional

from synthetic_generation.generators.base import BaseGenerator, GenerationResult

logger = logging.getLogger(__name__)


class ConversationalGenerator:
    """Generates multi-turn conversational samples."""

    def __init__(
        self,
        llm_client: Any,
        config: Dict[str, Any],
    ) -> None:
        self._llm = llm_client
        self._config = config

        self._num_turns = config.get("generation", {}).get("conversation", {}).get("num_turns", 3)
        self._include_coref = config.get("generation", {}).get("conversation", {}).get("include_coreference", True)
        self._include_ellipsis = config.get("generation", {}).get("conversation", {}).get("include_ellipsis", True)

    def generate(self, question: str, answer: str, chunk_id: str) -> Optional[Dict[str, Any]]:
        """Generate a multi-turn conversation from a QA pair."""
        prompt = self._build_prompt(question, answer)

        try:
            response = self._call_llm(prompt)
            return self._parse_response(response, chunk_id)
        except Exception as e:
            logger.warning(f"Conversational generation failed for chunk {chunk_id}: {e}")
            return self._fallback_conversation(question, answer, chunk_id)

    def _build_prompt(self, question: str, answer: str) -> str:
        """Build prompt for conversational generation."""
        template_path = Path(__file__).parent.parent / "prompts" / "conversational.txt"
        template = Path(template_path).read_text(encoding="utf-8")

        return template.format(
            question=question,
            answer=answer,
            num_turns=self._num_turns,
            chunk_id="",  # Will be filled after
        )

    def _call_llm(self, prompt: str) -> str:
        try:
            response = self._llm.generate(
                prompt,
                max_tokens=1024,
                temperature=0.5,
            )
            return response.text if hasattr(response, 'text') else str(response)
        except Exception as e:
            logger.error(f"LLM call failed: {e}")
            raise

    def _parse_response(self, response: str, chunk_id: str) -> Optional[Dict[str, Any]]:
        """Parse LLM response into conversation format."""
        text = str(response).strip()

        try:
            data = json.loads(text)
        except json.JSONDecodeError:
            # Try to extract JSON
            match = re.search(r'\{.*\}', text, re.DOTALL)
            if match:
                try:
                    data = json.loads(match.group(0))
                except json.JSONDecodeError:
                    return None
            else:
                return None

        # Validate required fields
        if not isinstance(data, dict):
            return None

        conversation = data.get("conversation", [])
        if not isinstance(conversation, list) or len(conversation) < 3:
            return None

        # Validate conversation format
        for turn in conversation:
            if not isinstance(turn, dict) or "role" not in turn or "content" not in turn:
                return None
            if turn["role"] not in ("user", "assistant"):
                return None

        return {
            "conversation": conversation,
            "target_chunk_id": chunk_id,
            "topic": data.get("topic", ""),
            "coreference_used": data.get("coreference_used", True),
            "ellipsis_used": data.get("ellipsis_used", True),
            "num_turns": len(conversation) // 2,
        }

    def _fallback_conversation(self, question: str, answer: str, chunk_id: str) -> Dict[str, Any]:
        """Fallback conversation when generation fails."""
        return {
            "conversation": [
                {"role": "user", "content": question},
                {"role": "assistant", "content": answer},
                {"role": "user", "content": "برای حقوقی هم همینه؟"},
                {"role": "assistant", "content": "بله، این правило برای هر دو مدل صدق می‌کند."},
                {"role": "user", "content": "جزئیات بیشتر بده"},
                {"role": "assistant", "content": answer[:200] + "..."},
            ],
            "target_chunk_id": chunk_id,
            "topic": "fallback",
            "coreference_used": True,
            "ellipsis_used": True,
            "num_turns": 3,
        }

"""Quality validator for synthetic data (LLM-as-judge)."""

from __future__ import annotations

import json
import logging
import re
from pathlib import Path
from typing import Any, Dict, List, Optional

logger = logging.getLogger(__name__)


@dataclass
class ValidationResult:
    """Result of validation."""
    relevance_score: float      # 0-1: semantic relevance to target
    accuracy_score: float       # 0-1: factual accuracy
    naturalness_score: float    # 0-1: natural Persian
    diversity_score: float      # 0-1: diversity from other samples
    overall_score: float        # 0-1: weighted average
    passes_threshold: bool      # overall >= threshold
    feedback: str               # qualitative feedback


class SyntheticValidator:
    """Validates synthetic data quality using LLM-as-judge."""

    def __init__(
        self,
        llm_client: Any,
        config: Dict[str, Any],
    ) -> None:
        self._llm = llm_client
        self._threshold = config.get("generation", {}).get("validation", {}).get("threshold", 0.7)
        self._validator_model = config.get("generation", {}).get("validation", {}).get("validator_model", "gemma2:27b")

        self._prompt_template = Path(__file__).parent.parent.joinpath("prompts", "validation.txt").read_text(encoding="utf-8")

        self._cache: Dict[str, ValidationResult] = {}

    def validate_qa(self, query: str, target_chunk: str, chunk_id: str) -> ValidationResult:
        """Validate a single QA pair."""
        cache_key = f"qa:{chunk_id}:{hash(query)}"
        if cache_key in self._cache:
            return self._cache[cache_key]

        result = self._validate(query, target_chunk)
        self._cache[cache_key] = result
        return result

    def validate_conversation(self, conversation: List[Dict], target_chunk: str, chunk_id: str) -> ValidationResult:
        """Validate a conversation."""
        # Use last user turn for validation
        user_turns = [t["content"] for t in conversation if t["role"] == "user"]
        if not user_turns:
            return ValidationResult(
                relevance_score=0, accuracy_score=0, naturalness_score=0,
                diversity_score=0, overall_score=0, passes_threshold=False,
                feedback="No user turns found"
            )

        # Validate last user turn (most specific)
        return self.validate_qa(user_turns[-1], target_chunk, chunk_id)

    def _validate(self, generated_text: str, target_chunk: str) -> ValidationResult:
        """Run LLM-as-judge validation."""
        prompt = self._build_prompt(generated_text, target_chunk)

        try:
            response = self._call_llm(prompt)
            return self._parse_validation(response)
        except Exception as e:
            logger.warning(f"Validation LLM call failed: {e}")
            return ValidationResult(
                relevance_score=0, accuracy_score=0, naturalness_score=0,
                diversity_score=0, overall_score=0, passes_threshold=False,
                feedback=f"Validation failed: {e}"
            )

    def _build_prompt(self, generated_text: str, target_chunk: str) -> str:
        template_path = Path(__file__).parent.parent / "prompts" / "validation.txt"
        template = Path(template_path).read_text(encoding="utf-8")

        return template.format(
            target_chunk=target_chunk[:2000],
            generated_text=generated_text[:500],
        )

    def _call_llm(self, prompt: str) -> str:
        try:
            response = self._llm.generate(
                prompt,
                max_tokens=512,
                temperature=0.2,  # Low temperature for consistent judging
            )
            return response.text if hasattr(response, 'text') else str(response)
        except Exception as e:
            logger.error(f"Validation LLM call failed: {e}")
            raise

    def _parse_validation(self, response: str) -> ValidationResult:
        """Parse validation response."""
        text = str(response).strip()

        try:
            # Try to extract JSON
            match = re.search(r'\{.*\}', text, re.DOTALL)
            if match:
                data = json.loads(match.group(0))
            else:
                data = json.loads(text)
        except json.JSONDecodeError:
            logger.warning(f"Failed to parse validation JSON: {text[:200]}")
            return ValidationResult(
                relevance_score=0, accuracy_score=0, naturalness_score=0,
                diversity_score=0, overall_score=0, passes_threshold=False,
                feedback="Failed to parse validation response"
            )

        scores = [
            data.get("relevance_score", 0),
            data.get("accuracy_score", 0),
            data.get("naturalness_score", 0),
            data.get("diversity_score", 0),
        ]
        overall = sum(scores) / len(scores) if scores else 0

        return ValidationResult(
            relevance_score=data.get("relevance_score", 0),
            accuracy_score=data.get("accuracy_score", 0),
            naturalness_score=data.get("naturalness_score", 0),
            diversity_score=data.get("diversity_score", 0),
            overall_score=overall,
            passes_threshold=overall >= self._threshold,
            feedback=data.get("feedback", ""),
        )

    def filter_batch(
        self,
        samples: List[Dict[str, Any]],
        chunk_texts: Dict[str, str],
    ) -> List[Dict[str, Any]]:
        """Filter a batch of samples, keeping only those that pass validation."""
        passed = []
        for sample in samples:
            chunk_id = sample.get("chunk_id") or sample.get("target_chunk_id") or sample.get("expected_chunk_id")
            if not chunk_id or chunk_id not in chunk_texts:
                continue

            # Get text to validate
            if "conversation" in sample:
                result = self.validate_conversation(sample["conversation"], chunk_texts[chunk_id], chunk_id)
            else:
                query = sample.get("query", "")
                result = self.validate_qa(query, chunk_texts[chunk_id], chunk_id)

            if result.passes_threshold:
                sample["validation"] = {
                    "overall_score": result.overall_score,
                    "relevance": result.relevance_score,
                    "accuracy": result.accuracy_score,
                    "naturalness": result.naturalness_score,
                    "diversity": result.diversity_score,
                }
                passed.append(sample)
            else:
                logger.debug(f"Sample rejected: {result.feedback} (score: {result.overall_score:.2f})")

        logger.info(f"Validation: {len(passed)}/{len(samples)} samples passed (threshold={self._threshold})")
        return passed

    def get_statistics(self, samples: List[Dict[str, Any]]) -> Dict[str, Any]:
        """Get validation statistics for a batch."""
        if not samples:
            return {}

        scores = [s.get("validation", {}).get("overall_score", 0) for s in samples if "validation" in s]
        if not scores:
            return {"count": 0}

        import statistics
        return {
            "count": len(scores),
            "mean": statistics.mean(scores),
            "median": statistics.median(scores),
            "min": min(scores),
            "max": max(scores),
            "passed": sum(1 for s in scores if s >= 0.7),
            "failed": sum(1 for s in scores if s < 0.7),
        }

